<?php
/**
 * Admin App - the plugin's screens, as React apps (admin-ui/).
 *
 * Same pattern as Imagina Updater: every menu entry is a WordPress admin page
 * whose PHP only prints a mount point; the bundle for that screen is enqueued
 * on that screen alone and talks to WIT_Admin_REST. The build lives in
 * assets/app (generated by `npm run build` in admin-ui/, shipped in the ZIP,
 * not in git).
 */

if (!defined('ABSPATH')) {
    exit;
}

class WIT_Admin_App {

    /** Screen slug => admin page slug. Existing slugs kept: bookmarks work. */
    const PAGES = array(
        'dashboard' => 'wpml-ia-translate',
        'content'   => 'wpml-ia-translate-content',
        'strings'   => 'wpml-ia-translate-strings',
        'history'   => 'wpml-ia-translate-logs',
        'settings'  => 'wpml-imagina-translate-settings',
    );

    private static $instance = null;

    /** @var array<string,string> admin page hook => screen slug */
    private $hooks = array();

    public static function instance() {
        if (is_null(self::$instance)) {
            self::$instance = new self();
        }
        return self::$instance;
    }

    private function __construct() {
        add_action('admin_menu', array($this, 'register_menu'));
        add_action('admin_enqueue_scripts', array($this, 'enqueue'));
    }

    public static function page_url($screen) {
        return admin_url('admin.php?page=' . self::PAGES[$screen]);
    }

    public function register_menu() {
        $render = array($this, 'render');

        $this->hooks[add_menu_page(
            __('Imagina Translate', 'wpml-imagina-translate'),
            __('IA Translate', 'wpml-imagina-translate'),
            'edit_posts',
            self::PAGES['dashboard'],
            $render,
            'dashicons-translation',
            30
        )] = 'dashboard';

        $entries = array(
            'dashboard' => array(__('Inicio', 'wpml-imagina-translate'), 'edit_posts'),
            'content'   => array(__('Contenidos', 'wpml-imagina-translate'), 'edit_posts'),
            'strings'   => array(__('Cadenas', 'wpml-imagina-translate'), 'manage_options'),
            'history'   => array(__('Historial', 'wpml-imagina-translate'), 'edit_posts'),
            'settings'  => array(__('Ajustes', 'wpml-imagina-translate'), 'manage_options'),
        );

        foreach ($entries as $screen => $entry) {
            if ($screen === 'strings' && !WIT_Strings::is_available()) {
                continue;
            }
            $hook = add_submenu_page(self::PAGES['dashboard'], $entry[0] . ' · Imagina Translate', $entry[0], $entry[1], self::PAGES[$screen], $render);
            if ($hook) {
                $this->hooks[$hook] = $screen;
            }
        }
    }

    /**
     * The mount point. Without a build, say so instead of a blank page.
     */
    public function render() {
        $screen = $this->current_screen_slug();

        if (!self::is_built()) {
            echo '<div class="wrap"><div class="notice notice-error"><p>';
            esc_html_e('Falta la interfaz compilada del plugin (assets/app). Instala el ZIP publicado, o ejecuta «npm ci && npm run build» en admin-ui/.', 'wpml-imagina-translate');
            echo '</p></div></div>';
            return;
        }

        printf('<div id="wit-%s" class="wit-root"></div>', esc_attr($screen ?: 'dashboard'));
    }

    public static function is_built() {
        return file_exists(WIT_PLUGIN_DIR . 'assets/app/app.asset.php');
    }

    private function current_screen_slug() {
        $page = isset($_GET['page']) ? sanitize_key(wp_unslash($_GET['page'])) : ''; // phpcs:ignore WordPress.Security.NonceVerification
        $slug = array_search($page, self::PAGES, true);

        return $slug === false ? '' : $slug;
    }

    public function enqueue($hook) {
        if (!isset($this->hooks[$hook]) || !self::is_built()) {
            return;
        }

        $screen = $this->hooks[$hook];
        $asset  = include WIT_PLUGIN_DIR . 'assets/app/app.asset.php';
        $ver    = is_array($asset) && isset($asset['version']) ? $asset['version'] : WIT_VERSION;

        wp_enqueue_style('wit-app', WIT_PLUGIN_URL . 'assets/app/app.css', array(), $ver);
        wp_enqueue_script('wit-' . $screen, WIT_PLUGIN_URL . 'assets/app/' . $screen . '.js', array(), $ver, true);

        // The bundles are ES modules (Vite).
        add_filter('script_loader_tag', function ($tag, $handle) use ($screen) {
            return $handle === 'wit-' . $screen ? str_replace('<script ', '<script type="module" ', $tag) : $tag;
        }, 10, 2);

        wp_localize_script('wit-' . $screen, 'witConfig', $this->config());
    }

    /**
     * Everything a screen needs before its first request.
     *
     * @return array
     */
    private function config() {
        $wpml  = WIT_WPML_Integration::instance();
        $pages = array();
        foreach (array_keys(self::PAGES) as $slug) {
            $pages[$slug] = self::page_url($slug);
        }

        $types = array();
        foreach (get_post_types(array('public' => true), 'objects') as $type) {
            if (in_array($type->name, array('attachment', 'e-floating-buttons', 'elementor_library'), true)) {
                continue;
            }
            if (WIT_WPML_Native::post_type_mode($type->name) === 'do_not_translate') {
                continue;
            }
            $types[] = array('name' => $type->name, 'label' => $type->labels->name);
        }

        $languages = array();
        foreach ($wpml->get_active_languages() as $language) {
            $languages[] = array('code' => $language['code'], 'name' => $language['name'], 'default' => (bool) $language['default']);
        }

        return array(
            'adminUrl'        => esc_url_raw(rest_url(WIT_Admin_REST::NAMESPACE_ . '/')),
            'nonce'           => wp_create_nonce('wp_rest'),
            'locale'          => str_replace('_', '-', get_user_locale()),
            'currentUser'     => wp_get_current_user()->display_name,
            'pages'           => $pages,
            'canManage'       => current_user_can('manage_options'),
            'version'         => WIT_VERSION,
            'languages'       => $languages,
            'defaultLanguage' => $wpml->get_default_language(),
            'postTypes'       => $types,
            'features'        => array(
                'strings'   => WIT_Strings::is_available(),
                'realWpml'  => WIT_WPML_Native::is_active(),
                'abilities' => WIT_Abilities::is_supported(),
                'apiKey'    => WIT_Settings::instance()->has_api_key(),
            ),
        );
    }
}
